package com.tekwatt.telemetry.service;import com.tekwatt.telemetry.dto.*;import com.tekwatt.telemetry.entity.TelemetryReading;import com.tekwatt.telemetry.repository.TelemetryRepository;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service@Transactional public class TelemetryService{private final TelemetryRepository repo;public TelemetryService(TelemetryRepository r){repo=r;}public TelemetryResponse create(TelemetryRequest r){return TelemetryResponse.from(repo.save(entity(r)));}public List<TelemetryResponse>batch(TelemetryBatchRequest r){return repo.saveAll(r.readings().stream().map(this::entity).toList()).stream().map(TelemetryResponse::from).toList();}@Transactional(readOnly=true)public List<TelemetryResponse>history(UUID chargerId,Instant from,Instant to){Instant end=to==null?Instant.now():to;Instant start=from==null?end.minus(Duration.ofHours(24)):from;if(start.isAfter(end))throw new IllegalArgumentException("from must not be after to");return repo.findAllByChargerIdAndSampledAtBetweenOrderBySampledAtAsc(chargerId,start,end).stream().map(TelemetryResponse::from).toList();}@Transactional(readOnly=true)public List<TelemetryResponse>latest(UUID connectorId){return repo.findTop100ByConnectorIdOrderBySampledAtDesc(connectorId).stream().map(TelemetryResponse::from).toList();}private TelemetryReading entity(TelemetryRequest r){return new TelemetryReading(r.tenantId(),r.chargerId(),r.connectorId(),r.sessionId(),r.transactionId(),r.measurand(),r.value(),r.unit(),r.phase(),r.context(),r.location(),r.sampledAt());}}
